def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row: counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    row_cols = {r: sorted(c for rr, c in pts if rr == r) for r in range(h)}
    col_rows = {c: sorted(r for r, cc in pts if cc == c) for c in range(w)}
    out = [row[:] for row in grid]
    def paint(r, c):
        if out[r][c] == bg: out[r][c] = 2
    rectangles=[]
    occupied=[r for r in range(h) if len(row_cols[r])>=2]
    for i,r1 in enumerate(occupied):
        for r2 in occupied[i+1:]:
            common=sorted(set(row_cols[r1]) & set(row_cols[r2]))
            if len(common)<2: continue
            c1,c2=common[0],common[-1]
            if c1 not in (row_cols[r1][0],row_cols[r2][0]): continue
            if c2 not in (row_cols[r1][-1],row_cols[r2][-1]): continue
            if not any(col_rows[c][0]==r1 and col_rows[c][-1]==r2 for c in (c1,c2)): continue
            rectangles.append((r1,r2,c1,c2))
    edge_rows=set(); edge_cols=set()
    for r1,r2,c1,c2 in rectangles:
        edge_rows.update((r1,r2)); edge_cols.update((c1,c2))
        for c in range(c1,c2+1): paint(r1,c); paint(r2,c)
        for r in range(r1,r2+1): paint(r,c1); paint(r,c2)
    for r,cols in row_cols.items():
        if r not in edge_rows and len(cols)>=4:
            for c in range(cols[0],cols[-1]+1): paint(r,c)
    for c,rows in col_rows.items():
        if c not in edge_cols and len(rows)>=4:
            for r in range(rows[0],rows[-1]+1): paint(r,c)
    top=min(r for r,c in pts); bottom=max(r for r,c in pts)
    left=min(c for r,c in pts); right=max(c for r,c in pts)
    for c in range(left,right+1): paint(top,c); paint(bottom,c)
    for r in range(top,bottom+1): paint(r,left); paint(r,right)
    return out

